                var label = waiting ? text('cinema_loading', 'Loading…') : failed ? text('cinema_retry', 'Try again') : text('cinema_load_more', 'Load more');
                moreBtn.toggleClass('is-loading', waiting).attr({ 'aria-label': label, 'aria-disabled': waiting ? 'true' : 'false', 'aria-busy': waiting ? 'true' : 'false' });
                moreBtn.find('.cx-btn__label').text(label);
