                sortBtn.attr('aria-label', sortLabel).find('.cx-btn__label').empty().append($('<span class="cx-sort__prefix"></span>').text(text('cinema_sort', 'Sort') + ': '), document.createTextNode(sortName(view.sort)));
                list = sortTitles(mediaFilter(all[view.type] || [], view.media), view.sort);
                if (filtered) { filtered.remove(); filtered = null; }
