                while (keep && !grid.find(keep) && shownCount < list.length) more();
                drawn = signature();
                if (!list.length) filtered = page.state('cx-state--filtered', text('cinema_filter_empty_title', 'Nothing matches these filters'), text('cinema_filter_empty_text', ''),
                    [{ label: text('cinema_reset_filters', 'Reset filters'), icon: 'arrow', action: function () { view.media = ''; render('media'); } }], grid.el);
                head.find('.cx-page-head__sub').text(text('cinema_titles_count', 'Titles') + ': ' + list.length + ' · ' + text('title_' + view.type, view.type));
                page.recollect(target || (groupName ? activeIn(groupName) : null));
