            page.hooks.focus = function () { return filters.find('[data-group="media"] .is-active:visible')[0] || grid.el.find('.selector')[0] || filters.find('.is-active')[0]; };
            function current() { return parseInt(object.page || first, 10) || first; }

            function raw() { try { return Lampa.Favorite.get({ type: object.type }) || []; } catch (e) { return []; } }
            function signature() { return raw().map(entryKey).join(','); }
            function paint() {
                var count = mediaFilter(raw(), object.filter).length;
                head.find('.cx-page-head__sub').text([text('cinema_titles_count', 'Titles') + ': ' + count, total > 1 ? text('cinema_page', 'Page') + ' ' + current() + ' / ' + total : ''].filter(Boolean).join(' · '));
            }
