                emptyState = page.state('cx-state--empty',
                    narrowed ? text('cinema_filter_empty_title', 'Nothing matches these filters') : text(history ? 'empty_history_title' : 'empty_bookmark_title', ''),
                    narrowed ? text('cinema_filter_empty_text', '') : text(history ? 'empty_history_text' : 'empty_bookmark_text', ''), actions, grid.el);
